import { useId } from "react";
import "./SettingsToggleRow.css";

export interface SettingsToggleRowProps {
  label: string;
  hint: string;
  checked: boolean;
  onChange: (checked: boolean) => void;
}

export function SettingsToggleRow({
  label,
  hint,
  checked,
  onChange,
}: SettingsToggleRowProps) {
  const labelId = useId();
  const hintId = useId();

  return (
    <div className="smr-row">
      <div className="smr-text">
        <span id={labelId} className="smr-label">
          {label}
        </span>
        <span id={hintId} className="smr-hint">
          {hint}
        </span>
      </div>
      <button
        type="button"
        role="switch"
        aria-checked={checked}
        aria-labelledby={labelId}
        aria-describedby={hintId}
        className={`smr-switch${checked ? " smr-switch--on" : ""}`}
        onClick={() => onChange(!checked)}
      >
        <span className="smr-thumb" aria-hidden="true" />
      </button>
    </div>
  );
}
```

