/*
 * SettingsToggleRow
 * Colors are scoped to .smr-row through custom properties so the component
 * carries its own day/night palette. Night mode is selected by an ancestor
 * carrying data-theme="night" (set by the app shell).
 */

.smr-row {
  --smr-surface: transparent;
  --smr-text: #1f2a2e;
  --smr-muted: #5d6b70;
  --smr-track-off: #d4dadc;
  --smr-track-on: #3f7d72;
  --smr-thumb: #ffffff;
  --smr-focus: #2f6b61;
  --smr-border: rgba(31, 42, 46, 0.12);

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 44px;
  padding: 14px 0;
  border-bottom: 1px solid var(--smr-border);
  background: var(--smr-surface);
  color: var(--smr-text);
  font-family: inherit;
}

[data-theme="night"] .smr-row {
  --smr-text: #e4ebed;
  --smr-muted: #9aa8ad;
  --smr-track-off: #3a4649;
  --smr-track-on: #6fb3a5;
  --smr-thumb: #13191b;
  --smr-focus: #8fd0c2;
  --smr-border: rgba(228, 235, 237, 0.1);
}

.smr-text {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.smr-label {
  font-size: 15px;
  font-weight: 500;
  line-height: 1.3;
  color: var(--smr-text);
}

.smr-hint {
  font-size: 13px;
  line-height: 1.4;
  color: var(--smr-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.smr-switch {
  position: relative;
  flex: 0 0 auto;
  width: 44px;
  height: 24px;
  margin: 0;
  padding: 0;
  border: none;
  border-radius: 999px;
  background: var(--smr-track-off);
  cursor: pointer;
  transition: background-color 180ms ease;
  -webkit-tap-highlight-color: transparent;
}

.smr-switch--on {
  background: var(--smr-track-on);
}

.smr-switch:focus {
  outline: none;
}

.smr-switch:focus-visible {
  outline: 2px solid var(--smr-focus);
  outline-offset: 3px;
}

.smr-thumb {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--smr-thumb);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
  transition: transform 180ms ease;
}

.smr-switch--on .smr-thumb {
  transform: translateX(20px);
}

@media (prefers-reduced-motion: reduce) {
  .smr-switch,
  .smr-thumb {
    transition: none;
  }
}
